import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.DSg0KOwT.js";const g=JSON.parse('{"title":"Managed platforms","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/alternative-log-retrieval/managed-platforms.md","filePath":"user-guide/alternative-log-retrieval/managed-platforms.md"}'),o={name:"user-guide/alternative-log-retrieval/managed-platforms.md"};function n(i,e,l,p,d,h){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="managed-platforms" tabindex="-1">Managed platforms <a class="header-anchor" href="#managed-platforms" aria-label="Permalink to &quot;Managed platforms&quot;">​</a></h1><p>Where to find the Spark event log on each managed platform.</p><h2 id="amazon-emr" tabindex="-1">Amazon EMR <a class="header-anchor" href="#amazon-emr" aria-label="Permalink to &quot;Amazon EMR&quot;">​</a></h2><p>EMR turns event logging on by default. On the cluster, the logs sit on HDFS under <code>/var/log/spark/apps/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/spark/apps/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/spark/apps/application_XXXX_XXXX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>If your cluster sets <code>spark.eventLog.dir</code> to an S3 path, download the file from there instead (for example with <code>aws s3 cp</code>). AWS&#39;s <a href="https://aws.github.io/aws-emr-best-practices/docs/benchmarks/Analyzing/retrieve_event_logs/" target="_blank" rel="noreferrer">EMR best-practices guide</a> covers both.</p><h2 id="aws-glue" tabindex="-1">AWS Glue <a class="header-anchor" href="#aws-glue" aria-label="Permalink to &quot;AWS Glue&quot;">​</a></h2><p>Glue writes event logs to S3 when the job has the Spark UI turned on. In the job parameters:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--enable-spark-ui true</span></span>
<span class="line"><span>--spark-event-logs-path s3://my-bucket/spark-events/</span></span>
<span class="line"><span>--enable-spark-ui-legacy-path true</span></span></code></pre></div><p>Glue has two log formats: Standard, for its own console, and Legacy, which AWS documents for viewing on a Spark History Server. Ask for Legacy, as the last parameter above does, or pick it in the console under <strong>Spark UI logging and monitoring configuration</strong>.</p><p>After the run, download the file, or the rolling-log directory when the job uses <code>spark.eventLog.rolling.enabled</code>, from that S3 path. See <a href="https://docs.aws.amazon.com/glue/latest/dg/monitor-spark-ui-jobs.html" target="_blank" rel="noreferrer">Enabling the Apache Spark web UI for AWS Glue jobs</a>.</p><h2 id="databricks" tabindex="-1">Databricks <a class="header-anchor" href="#databricks" aria-label="Permalink to &quot;Databricks&quot;">​</a></h2><p>Set up compute log delivery on the cluster or job compute before it runs: <strong>Advanced &gt; Logging</strong>, then pick a Unity Catalog volume, S3 or DBFS path. Databricks delivers driver, worker and event logs into a subfolder of that path named after the cluster ID, and keeps delivering until the compute shuts down. Copy the event log from there. See <a href="https://docs.databricks.com/aws/en/compute/configure#compute-log-delivery" target="_blank" rel="noreferrer">compute log delivery</a>.</p><h2 id="dataproc" tabindex="-1">Dataproc <a class="header-anchor" href="#dataproc" aria-label="Permalink to &quot;Dataproc&quot;">​</a></h2><p>Google Cloud Dataproc (also called Managed Service for Apache Spark) saves Spark job history to the cluster&#39;s temp bucket, in its <code>/spark-job-history</code> directory, unless the cluster sets <code>spark.eventLog.dir</code> somewhere else. Download the file with <code>gcloud storage cp</code>. See <a href="https://cloud.google.com/dataproc/docs/concepts/jobs/history-server" target="_blank" rel="noreferrer">Persistent History Server</a>.</p>`,15)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
